map "https://fhir.hl7.at/elga/cda2fhir/r4/StructureMap/at-cda-emed-to-fhir-bundle" = "CdaEmedToFhirBundle"

//
// Mapping ELGA-CDA eMedikation to FHIR
//

conceptmap "cda-emed-clinicaldocument-code-2-fhir-category" {
  prefix s = "http://loinc.org"

  s: "56445-0" == s: "56445-0"
  s: "57833-6" == s: "57833-6"
  s: "60593-1" == s: "60593-1"
}

conceptmap "at-cda-to-fhir-medication-code" {
  prefix s = "http://example.org/cda/emed/medication/code",
         t = "http://www.whocc.no/atc"

  s: "code1" == t: "A01"
  s: "code2" == t: "B01"
  s: "code3" == t: "C01"
}

uses "http://hl7.org/cda/stds/core/StructureDefinition/ClinicalDocument" alias ClinicalDocument as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Author" alias Author as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssignedAuthor" alias AssignedAuthor as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssignedEntity" alias AssignedEntity as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/AssociatedEntity" alias AssociatedEntity as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/CustodianOrganization" alias CustodianOrganization as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Section" alias Section as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/PatientRole" alias PatientRole as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/StructuredBody" alias StructuredBody as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Observation" alias CDAObservation as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Performer2" alias Performer as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Procedure" alias Procedure as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Organizer" alias Organizer as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Participant1" alias Participant as source
uses "http://hl7.org/cda/stds/core/StructureDefinition/Act" alias Act as source

uses "http://hl7.org/fhir/4.3/StructureDefinition/Bundle" alias Bundle as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Composition" alias Composition as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Patient" alias Patient as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Person" alias Person as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Practitioner" alias Practitioner as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/PractitionerRole" alias PractitionerRole as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Organization" alias Organization as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/DiagnosticReport" alias DiagnosticReport as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/ServiceRequest" alias ServiceRequest as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Observation" alias Observation as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/Medication" alias Medication as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/MedicationDispense" alias MedicationDispense as target
uses "http://hl7.org/fhir/4.3/StructureDefinition/MedicationRequest" alias MedicationRequest as target

imports "http://hl7.at/fhir/HL7ATCoreProfiles/4.0.1/StructureMap/at-cda-to-fhir-types"


// _________________________ Document Level Template  _________________________

group CdaEmedToFhirBundle(source cda: ClinicalDocument, target fhir_patient: Patient, target fhir_composition: Composition, target fhir_bundle: Bundle) { // Mapping ELGA-CDA eMedikation to FHIR
  cda ->   
    // at least on Bundle level the profile is to be set
    fhir_bundle.meta as fhir_bundle_meta,
    fhir_bundle_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-bundle'
    then {
      // map the CDA header
      cda then CdaEmedHeaderToFhirComposition(cda, fhir_composition, fhir_patient, fhir_bundle) "CdaEmedHeaderToFhirComposition";
      cda then CdaEmedHeaderToFhir(cda, fhir_composition, fhir_patient, fhir_bundle) "CdaEmedHeaderToFhir"; 

      // map the CDA body
      //ClinicalDocument/component
      cda.component as cda_component then {
        // ClinicalDocument/component/structuredBody
        cda_component.structuredBody as cda_structuredBody
          then CdaEmedBodyToFhir(cda, cda_structuredBody, fhir_composition, fhir_patient, fhir_bundle);
      };
    } "CdaEmedToFhirBundle"; 
}

// _________________________ Header Level Templates _________________________

group CdaEmedHeaderToFhirComposition(source cda : ClinicalDocument, target fhir_composition : Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) extends CdaHeaderToFhirComposition {
   
  cda.code as cda_code then {

  // Set Profile of Composition
  cda_code ->
    fhir_composition.meta as fhir_composition_meta,
    fhir_composition_meta.profile = 'https://fhir.hl7.at/elga/aps/r4/StructureDefinition/at-aps-composition' "CdaEmedSetAPSCompositionProfile";

   // ClinicalDocument/code -> Composition.category
   cda_code.code as code_code ->
    fhir_composition.category as fhir_composition_category,
    fhir_composition_category.coding = translate(code_code, '#cda-emed-clinicaldocument-code-2-fhir-category' , 'Coding') "CdaEmedCodeToFhirCompositionCategory";

   // ClinicalDocument/code/translation (document class) -> Composition.type
   // for CDA eMedication, translation is fixed to 52471-0 LOINC
   cda_code.translation -> fhir_composition.type "CdaEmedCodeTranslationToFhirCompositionType";
   // in case CDA does not have translation, the Composition.type will be explicitly set (currently set to 60591-5 for valid APS Bundle)
   cda_code where cda_code.translation.exists().not() ->
     fhir_composition.type = create('CodeableConcept') as type_coding,
     type_coding.coding = create('Coding') as coding_coding,
     coding_coding.system = 'http://loinc.org',
     coding_coding.code = '60591-5'
     "CdaEmedMissingCodeTranslationToFhirCompositionType";

  } "CdaEmedCodeToFhirComposition";
   
}

group CdaEmedHeaderToFhir(source cda: ClinicalDocument, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) extends CdaHeaderToFhir {
}

// _________________________ Body Level Templates ____________________________

group CdaEmedBodyToFhir(source cda: ClinicalDocument, source cda_structuredBody: StructuredBody, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) {
   
  // prefill required APS sections in order to have a valid APS instance
  cda_structuredBody ->
  // section problems
    fhir_composition.section as fhir_composition_problems_section,
    fhir_composition_problems_section.title = 'Gesundheitsprobleme und Risiken (Problems)',
    fhir_composition_problems_section.code as fhir_composition_problems_section_code,
    fhir_composition_problems_section_code.coding as fhir_composition_problems_section_code_coding,
    fhir_composition_problems_section_code_coding.system = 'http://loinc.org',
    fhir_composition_problems_section_code_coding.code = '11450-4',
    fhir_composition_problems_section.emptyReason as fhir_composition_problems_section_emptyReason,
    fhir_composition_problems_section_emptyReason.coding as fhir_composition_problems_section_emptyReason_coding,
    fhir_composition_problems_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_problems_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_problems_section.text as fhir_composition_problems_section_text,
    fhir_composition_problems_section_text.status = 'empty',
    fhir_composition_problems_section_text.div = append('Kein Text für diese Section vorhanden.'),

    // section allergies
    fhir_composition.section as fhir_composition_allergies_section,
    fhir_composition_allergies_section.title = 'Allergien und Intoleranzen (Allergies and Intolerances)',
    fhir_composition_allergies_section.code as fhir_composition_allergies_section_code,
    fhir_composition_allergies_section_code.coding as fhir_composition_allergies_section_code_coding,
    fhir_composition_allergies_section_code_coding.system = 'http://loinc.org',
    fhir_composition_allergies_section_code_coding.code = '48765-2',
    fhir_composition_allergies_section.emptyReason as fhir_composition_allergies_section_emptyReason,
    fhir_composition_allergies_section_emptyReason.coding as fhir_composition_allergies_section_emptyReason_coding,
    fhir_composition_allergies_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_allergies_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_allergies_section.text as fhir_composition_allergies_section_text,
    fhir_composition_allergies_section_text.status = 'empty',
    fhir_composition_allergies_section_text.div = append('Kein Text für diese Section vorhanden.'),

    // section medications
    fhir_composition.section as fhir_composition_medications_section,
    fhir_composition_medications_section.title = 'Medikationsliste (Medication Summary)',
    fhir_composition_medications_section.code as fhir_composition_medications_section_code,
    fhir_composition_medications_section_code.coding as fhir_composition_medications_section_code_coding,
    fhir_composition_medications_section_code_coding.system = 'http://loinc.org',
    fhir_composition_medications_section_code_coding.code = '10160-0',
    fhir_composition_medications_section.emptyReason as fhir_composition_medications_section_emptyReason,
    fhir_composition_medications_section_emptyReason.coding as fhir_composition_medications_section_emptyReason_coding,
    fhir_composition_medications_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_medications_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_medications_section.text as fhir_composition_medications_section_text,
    fhir_composition_medications_section_text.status = 'empty',
    fhir_composition_medications_section_text.div = append('Kein Text für diese Section vorhanden.'),

    // section procedures
    fhir_composition.section as fhir_composition_procedures_section,
    fhir_composition_procedures_section.title = 'Eingriffe und Therapien (History of Procedures)',
    fhir_composition_procedures_section.code as fhir_composition_procedures_section_code,
    fhir_composition_procedures_section_code.coding as fhir_composition_procedures_section_code_coding,
    fhir_composition_procedures_section_code_coding.system = 'http://loinc.org',
    fhir_composition_procedures_section_code_coding.code = '47519-4',
    fhir_composition_procedures_section.emptyReason as fhir_composition_procedures_section_emptyReason,
    fhir_composition_procedures_section_emptyReason.coding as fhir_composition_procedures_section_emptyReason_coding,
    fhir_composition_procedures_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_procedures_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_procedures_section.text as fhir_composition_procedures_section_text,
    fhir_composition_procedures_section_text.status = 'empty',
    fhir_composition_procedures_section_text.div = append('Kein Text für diese Section vorhanden.'),

    // section medical devices
    fhir_composition.section as fhir_composition_devices_section,
    fhir_composition_devices_section.title = 'Implantate, medizinische Geräte (Medical Devices)',
    fhir_composition_devices_section.code as fhir_composition_devices_section_code,
    fhir_composition_devices_section_code.coding as fhir_composition_devices_section_code_coding,
    fhir_composition_devices_section_code_coding.system = 'http://loinc.org',
    fhir_composition_devices_section_code_coding.code = '46264-8',
    fhir_composition_devices_section.emptyReason as fhir_composition_devices_section_emptyReason,
    fhir_composition_devices_section_emptyReason.coding as fhir_composition_devices_section_emptyReason_coding,
    fhir_composition_devices_section_emptyReason_coding.system = 'http://terminology.hl7.org/CodeSystem/list-empty-reason',
    fhir_composition_devices_section_emptyReason_coding.code = 'unavailable',
    fhir_composition_devices_section.text as fhir_composition_devices_section_text,
    fhir_composition_devices_section_text.status = 'empty',
    fhir_composition_devices_section_text.div = append('Kein Text für diese Section vorhanden.')
    "prefillRequiredApsSections";

    // structuredBody/component/section -> Composition.section
    cda_structuredBody.component as cda_structuredBody_component then {
     cda_structuredBody_component.section as cda_section then CdaEmedSectionToFhir(cda, cda_section, fhir_composition, fhir_patient, fhir_bundle);
   } "CdaEmedBodyToFhir";
}

group CdaEmedSectionToFhir(source cda: ClinicalDocument, source cda_section: Section, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) {
   
  // Only map section if it contains Medication entries (LOINC code 10160-0)
   cda_section as cda_section where ($this.code.code = '10160-0') then {
      cda_section.entry as cda_entry then {
         cda_entry.supply as cda_entry_supply then {
          // section/entry/supply -> MedicationDispense
            cda_entry_supply where ($this.templateId.root = '1.2.40.0.34.11.8.2.3.1') then CdaEmedAbgabeEntryToFhir(cda, cda_entry_supply, fhir_composition, fhir_patient, fhir_bundle) "CdaEmedAbgabeEntryToFhir";
          // section/entry/supply -> MedicationRequest
            //cda_entry_supply where ($this.templateId.root = '1.2.40.0.34.11.8.1.3.1') then CdaEmedVerordnungEntryToFhir(cda, cda_entry_supply, fhir_composition, fhir_patient, fhir_bundle) "CdaEmedVerordnungEntryToFhir";
         }
      }
   } "CdaEmedSectionToFhir";
}

group CdaEmedAbgabeEntryToFhir(source cda: ClinicalDocument, source cda_supply: Act, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) {
  
  
  cda_supply as cda_supply then {
    // create FHIR MedicationDispense resource for the supplied medication dispense entry
    fhir_bundle.entry as fhir_bundle_entry,
        fhir_bundle_entry.resource = create('MedicationDispense') as fhir_medicationDispense,
        fhir_medicationDispense.id = uuid() as fhir_medicationDispense_id,
        fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_medicationDispense_id),
        fhir_composition.section where ($this.code.coding.code = '10160-0') = create('Reference') as fhir_composition_medication_reference,
        fhir_composition_medication_reference.reference = append('urn:uuid:', fhir_medicationDispense_id),
        fhir_medicationDispense_id.type = 'MedicationDispense' then {
          
          // supply/id/@root -> MedicationDispense.identifier
          cda_supply.id -> fhir_medicationDispense.identifier;
          // supply/code -> MedicationDispense.status (mapping of CDA supply code to FHIR MedicationDispense.status to be defined in detail based on actual CDA instances, currently mapped to "completed" for all supplies)
          cda_supply.code -> fhir_medicationDispense.status;
          // supply/quantity -> MedicationDispense.quantity
          cda_supply.quantity -> fhir_medicationDispense.quantity;
          // supply/product -> Medication
          cda_supply.product as cda_product then CdaEmedProductToFhirMedication(cda, cda_product, fhir_composition, fhir_patient, fhir_bundle);
          // supply/author -> either Practitioner or PractitionerRole depending on the presence of assignedEntity or representedOrganization within the author
          cda_supply.author as cda_author then CdaEmedSupplyAuthorToFhir(cda, cda_author, fhir_composition, fhir_patient, fhir_bundle);
          // supply/entryRelationship -> ??
          //cda_supply.entryRelationship as cda_entryRelationship then CdaEmedSupplyEntryRelationshipToFhir(cda, cda_entryRelationship, fhir_composition, fhir_patient, fhir_bundle);
        }
   }
}

group CdaEmedProductToFhirMedication(source cda: ClinicalDocument, source cda_product: Act, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) {
   
    // create FHIR Medication resource for the supplied product
    fhir_bundle.entry as fhir_bundle_entry,
    fhir_bundle_entry.resource = create('Medication') as fhir_medication,
    fhir_medication.id = uuid() as fhir_medication_id,
    fhir_bundle_entry.fullUrl = append('urn:uuid:', fhir_medication_id),
    fhir_composition.section = create('Reference') as fhir_composition_section_reference,
    fhir_composition_section_reference.reference = append('urn:uuid:', fhir_medication_id),
    fhir_composition_section_reference.type = 'Medication' then {

      // fill FHIR Medication resource with information from CDA product
      cda_product.manufacturedProduct as cda_product_manufacturedProduct then {
        cda_product_manufacturedProduct.manufacturedMaterial as cda_product_manufacturedMaterial then {

          // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/code/translation -> Medication.identifier
          // cda_product_manufacturedMaterial.code as cda_product_manufacturedMaterial_code then {
          // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/code -> Medication.code
          // cda_product_manufacturedMaterial_code -> fhir_medication.code;
          // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/code -> Medication.code.coding
          // cda_product_manufacturedMaterial_code.translation -> fhir_medication.identifier;
          
        
          // draft fhir_medication.code
          cda_product_manufacturedMaterial.code as cda_product_manufacturedMaterial_code -> fhir_medication.code as fhir_medication_code then{

            // PZN aus Hauptcode
            cda_product_manufacturedMaterial_code where (codeSystem = '1.2.40.0.34.4.16') -> fhir_medication_code.coding as fhir_medication_code_coding_pzn then {
              cda_product_manufacturedMaterial_code.code -> fhir_medication_code_coding_pzn.code;
              fhir_medication_code_coding_pzn.system = '1.2.40.0.34.4.16';
              fhir_medication_code_coding_pzn.display = 'Pharmazentralnummer';
            };

            // Zulassungsnummer aus translation
            cda_product_manufacturedMaterial_code.translation as cda_product_manufacturedMaterial_code_translation
              where (codeSystem = '1.2.40.0.34.4.17') -> fhir_medication_code.coding as fhir_medication_code_coding_zn_translation then {
              cda_product_manufacturedMaterial_code_translation.code -> fhir_medication_code_coding_zn_translation.code;
              fhir_medication_code_coding_zn_translation.system = '1.2.40.0.34.4.17';
              fhir_medication_code_coding_zn_translation.display = 'Zulassungsnummer';
            };

            // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/name -> Medication.code.text
            cda_product_manufacturedMaterial.name -> fhir_medication_code.text;
            
          };


          // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/formCode -> Medication.form
          cda_product_manufacturedMaterial.ns2:formCode as cda_product_manufacturedMaterial_formCode -> fhir_medication.form as fhir_medication_form then {
            fhir_medication_form_coding.system = 'https://termgit.elga.gv.at/CodeSystem/medikationdarreichungsform';

            cda_product_manufacturedMaterial_formCode.code -> fhir_medication_form_coding.code;
            cda_product_manufacturedMaterial_formCode.displayName -> fhir_medication_form_coding.display;
          };
          

          // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/asContent/containerPackagedMedicine/capacityQuantity -> Medication.amount
          cda_product_manufacturedMaterial.ns2:asContent as cda_product_manufacturedMaterial_asContent then {
            cda_product_manufacturedMaterial_asContent.ns2:containerPackagedMedicine as cda_product_manufacturedMaterial_asContent_containerPackagedMedicine then {
              cda_product_manufacturedMaterial_asContent_containerPackagedMedicine.ns2:capacityQuantity as cda_product_manufacturedMaterial_asContent_containerPackagedMedicine_capacityQuantity -> fhir_medication.amount as fhir_medication_amount then {

                // numerator
                cda_product_manufacturedMaterial_asContent_containerPackagedMedicine_capacityQuantity.value -> fhir_medication_amount.numerator.value;
                cda_product_manufacturedMaterial_asContent_containerPackagedMedicine_capacityQuantity.unit -> fhir_medication_amount.numerator.unit;

                // denominator fix
                fhir_medication_amount.denominator.value = '1';
                fhir_medication_amount.denominator.unit = 'Packung';

              };
            };
          };

          // TODO: aktive Wirksstoffe? Siehe IL s. 179
          // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/ingredient (1) -> Medication.ingredient
          cda_product_manufacturedMaterial.ns2:ingredient as cda_product_manufacturedMaterial_ingredient then {
            cda_product_manufacturedMaterial_ingredient.ns2:ingredient as cda_product_manufacturedMaterial_ingredient_ingredient -> fhir_medication.ingredient as fhir_medication_ingredient then {

              cda_product_manufacturedMaterial_ingredient_ingredient.ns2:code as cda_product_manufacturedMaterial_ingredient_ingredient_code -> fhir_medication_ingredient.itemCodeableConcept as fhir_medication_ingredient_itemCodeableConcept then {

                // Hauptcode
                cda_product_manufacturedMaterial_ingredient_ingredient_code
                  where (codeSystem = '2.16.840.1.113883.6.73')
                  -> fhir_medication_ingredient_itemCodeableConcept.coding as fhir_medication_ingredient_itemCodeableConcept_coding then {
                  cda_product_manufacturedMaterial_ingredient_ingredient_code.code -> fhir_medication_ingredient_itemCodeableConcept_coding.code;
                  fhir_medication_ingredient_itemCodeableConcept_coding.system = 'http://www.whocc.no/atc';
                  cda_product_manufacturedMaterial_ingredient_ingredient_code.displayName -> fhir_medication_ingredient_itemCodeableConcept_coding.display;                };

                // translation atc-deutsch-wido
                cda_product_manufacturedMaterial_ingredient_ingredient_code.translation as cda_product_manufacturedMaterial_ingredient_ingredient_code_translation
                  where (codeSystem = '1.2.276.0.76.5.558')
                  -> fhir_medication_ingredient_itemCodeableConcept.coding as fhir_medication_ingredient_itemCodeableConcept_coding_translation then {
                  cda_product_manufacturedMaterial_ingredient_ingredient_code_translation.code -> fhir_medication_ingredient_itemCodeableConcept_coding_translation.code;
                  fhir_medication_ingredient_itemCodeableConcept_coding_translation.system = 'atc-deutsch-wido';
                  cda_product_manufacturedMaterial_ingredient_ingredient_code_translation.displayName -> fhir_medication_ingredient_itemCodeableConcept_coding_translation.display;
                };

                // Name
                cda_product_manufacturedMaterial_ingredient_ingredient.ns2:name -> fhir_medication_ingredient_itemCodeableConcept.text;

              };
              
            };
          };


          // ClinicalDocument/component/structuredBody/section/entry/supply/product/manufacturedProduct/manufacturedMaterial/ingredient (2) -> Medication.ingredient
          cda_product_manufacturedMaterial.ns2:ingredient as cda_product_manufacturedMaterial_ingredient then {
            cda_product_manufacturedMaterial_ingredient.ns2:ingredient as cda_product_manufacturedMaterial_ingredient_ingredient -> fhir_medication.ingredient as fhir_medication_ingredient then {

              cda_product_manufacturedMaterial_ingredient_ingredient.ns2:code as cda_product_manufacturedMaterial_ingredient_ingredient_code -> fhir_medication_ingredient.itemCodeableConcept as fhir_medication_ingredient_itemCodeableConcept then {

                // AGES Wirkstoff
                cda_product_manufacturedMaterial_ingredient_ingredient_code
                  where (codeSystem = '1.2.40.0.34.5.156')
                  -> fhir_medication_ingredient_itemCodeableConcept.coding as fhir_medication_ingredient_itemCodeableConcept_coding then {
                  cda_product_manufacturedMaterial_ingredient_ingredient_code.code -> fhir_medication_ingredient_itemCodeableConcept_coding.code;
                  fhir_medication_ingredient_itemCodeableConcept_coding.system = 'Medikation_AGES_Wirkstoffe';
                  cda_product_manufacturedMaterial_ingredient_ingredient_code.displayName -> fhir_medication_ingredient_itemCodeableConcept_coding.display;
                };

                // Name
                cda_product_manufacturedMaterial_ingredient_ingredient.ns2:name -> fhir_medication_ingredient_itemCodeableConcept.text;

              };

            };
          };
        };
      };

}

group CdaEmedSupplyAuthorToFhir(source cda: ClinicalDocument, source cda_author: Author, target fhir_composition: Composition, target fhir_patient: Patient, target fhir_bundle: Bundle) {
    
  
  cda_author.assignedAuthor as cda_author_assignedAuthor where ($this.assignedAuthor.id.root = "1.2.40.0.36.99.1") then {

      // create FHIR Practitioner resource for the assignedAuthor
      fhir_bundle.entry as fhir_bundle_entry,
      fhir_bundle_entry.resource = create('Practitioner') as fhir_practitioner,
